import random
from itertools import product
from typing import Callable, Dict, List, Optional, Tuple

Literal = Tuple[int, bool]
Clause = List[Literal]
Formula = List[Clause]

def random_3sat(n_vars: int, m_clauses: int, seed: int = 0) -> Formula:
    rng = random.Random(seed)
    F: Formula = []
    for _ in range(m_clauses):
        vs = rng.sample(range(1, n_vars + 1), k=min(3, n_vars))
        F.append([(v, rng.choice([True, False])) for v in vs])
    return F

def piece_count(n_vars: int, F: Formula) -> int:
    return 2 * n_vars + len(F) + 2

def satisfiable(F: Formula, n_vars: int) -> bool:
    for bits in product([False, True], repeat=n_vars):
        a = {i + 1: bits[i] for i in range(n_vars)}
        if all(any(a[v] == p for (v, p) in c) for c in F):
            return True
    return False

def main() -> None:
    for seed in range(5):
        n, m = 4, 6
        F = random_3sat(n, m, seed)
        print(f"seed={seed}  n={n} m={m}  pieces={piece_count(n, F)}  "
              f"solvable={satisfiable(F, n)}")

if __name__ == "__main__":
    main()

from enum import Enum
from typing import Callable, Dict, List, Tuple

class Edge(Enum):
    FLAT = "flat"; TAB = "tab"; BLANK = "blank"

def comp(e: Edge) -> Edge:
    return {Edge.FLAT: Edge.FLAT, Edge.TAB: Edge.BLANK, Edge.BLANK: Edge.TAB}[e]

def enc(v: bool) -> Edge:
    return Edge.TAB if v else Edge.BLANK

Literal = Tuple[int, bool]
Clause = List[Literal]

def trace(F: List[Clause], a: Dict[int, bool]) -> None:
    for j, c in enumerate(F, 1):
        placed = False
        for (v, p) in c:
            out = enc(a.get(v, False))          # variable output edge
            inp = comp(enc(p))                  # clause-piece input edge
            if inp == comp(out):                # they interlock
                print(f"clause {j}: literal (x{v}={p}) input {inp.value} "
                      f"snaps onto variable output {out.value}")
                placed = True
                break
        print(f"  -> clause piece {j} {'PLACED' if placed else 'CANNOT be placed'}")

def main() -> None:
    F = [[(1, True), (2, True), (3, False)], [(1, False), (3, True)]]
    a = {1: False, 2: True, 3: False}
    print("assignment:", a)
    trace(F, a)

if __name__ == "__main__":
    main()

